// Read Config from upstream Read Config node, build run context.
// Falls back to sensible defaults if Config sheet is empty.
const now = new Date();
const local = new Date(now.toLocaleString('en-US', { timeZone: 'UTC' }));
const pad = n => String(n).padStart(2, '0');
const run_id =
  `content_radar_${local.getFullYear()}${pad(local.getMonth() + 1)}${pad(local.getDate())}` +
  `_${pad(local.getHours())}${pad(local.getMinutes())}${pad(local.getSeconds())}`;

// Read first row of Config sheet (Read Config feeds in upstream).
const config = $input.first()?.json || {};

// Helpers
const str = (v, fb) => {
  const s = String(v ?? '').trim();
  return s.length ? s : fb;
};
const num = (v, fb) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : fb;
};

const time_window_days = num(config.time_window_days, 5);
const min_views = num(config.min_views, 5000);
const windowMs = now.getTime() - time_window_days * 24 * 60 * 60 * 1000;

// Default config — gets used if Config sheet is empty/missing.
// Tuned for AI/automation niche so the workflow does something useful on first run.
const DEFAULTS = {
  niche_name: 'AI for solopreneurs',
  keywords: 'ai automation, n8n, claude code, ai agents',
  hashtags_x: 'aiagents, aiautomation, claudecode, n8n',
  hashtags_instagram: 'aitools, claudecode, aiautomation, n8n',
  hashtags_tiktok: 'aiautomation, n8nworkflow, claudecode, aitools',
  hashtags_youtube: 'aiagents, claudecode, n8n, aishorts',
  language_output: 'english',
  platforms: 'x, instagram, tiktok'
};

return [{
  json: {
    run_id,
    scraped_at: now.toISOString(),
    nowMs: now.getTime(),
    windowMs,
    windowIso: new Date(windowMs).toISOString(),
    time_window_days,
    min_views,
    niche_name: str(config.niche_name, DEFAULTS.niche_name),
    keywords: str(config.keywords, DEFAULTS.keywords),
    hashtags_x: str(config.hashtags_x, DEFAULTS.hashtags_x),
    hashtags_instagram: str(config.hashtags_instagram, DEFAULTS.hashtags_instagram),
    hashtags_tiktok: str(config.hashtags_tiktok, DEFAULTS.hashtags_tiktok),
    hashtags_youtube: str(config.hashtags_youtube, DEFAULTS.hashtags_youtube),
    language_output: str(config.language_output, DEFAULTS.language_output).toLowerCase(),
    platforms: str(config.platforms, DEFAULTS.platforms),
    target_window: '00:00'  // legacy column kept for Raw_Posts schema
  }
}];

// Fan out the single config item into one item per enabled platform.
// Each emitted item carries the full ctx + a `platform` field so Switch can route.
const ctx = $input.first().json;

const platforms = String(ctx.platforms || 'x, instagram, tiktok')
  .split(',')
  .map(s => s.trim().toLowerCase())
  .map(p => p === 'twitter' ? 'x' : p)
  .filter(p => ['x', 'instagram', 'tiktok', 'youtube'].includes(p));

if (platforms.length === 0) {
  return [{ json: { _empty: true, stage: 'no_platforms', run_id: ctx.run_id } }];
}

return platforms.map(platform => ({
  json: { ...ctx, platform }
}));

// Build X / Twitter search input for apidojo/tweet-scraper.
// Each search term becomes a separate query — keywords + hashtags both included.
const ctx = $input.first().json;

const keywords = String(ctx.keywords || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const hashtags = String(ctx.hashtags_x || '')
  .split(',').map(s => s.trim()).filter(Boolean)
  .map(h => '#' + h.replace(/^#/, ''));

const searchTerms = [...keywords, ...hashtags];

if (searchTerms.length === 0) {
  return [{ json: { _empty: true, stage: 'prepare_x_no_terms', run_id: ctx.run_id, platform: 'x' } }];
}

// 30 tweets per term, sorted by Top to surface viral content (not just newest).
const apifyBody = {
  searchTerms,
  maxItems: 30 * searchTerms.length,
  sort: 'Top'
};

return [{ json: { ...ctx, apifyBody, platform: 'x' } }];

// Normalize X / Twitter posts (apidojo/tweet-scraper hashtag/search output).
// We're scraping by hashtag/keyword now, so author is whoever posted — no creator map.
const ctx = $('Initialize Run').first().json;
const tweets = $input.all();

if (tweets.length === 0) {
  return [{ json: { _empty: true, stage: 'normalize_x', run_id: ctx.run_id } }];
}

function pickAuthor(t) {
  return String(
    (t.author && (t.author.userName || t.author.username)) ||
    (t.user && (t.user.screen_name || t.user.username)) ||
    t.username || t.authorUsername || ''
  ).toLowerCase();
}

function pickFollowers(t) {
  return Number(
    (t.author && (t.author.followers || t.author.followersCount)) ||
    (t.user && (t.user.followers_count || t.user.followersCount)) ||
    0
  );
}

function pickImage(t) {
  if (Array.isArray(t.media) && t.media[0]) {
    const f = t.media[0];
    if (typeof f === 'string') return f;
    return f.url || f.media_url_https || f.mediaUrl || '';
  }
  if (t.entities && Array.isArray(t.entities.media) && t.entities.media[0]) {
    return t.entities.media[0].media_url_https || '';
  }
  return '';
}

const out = [];
for (const item of tweets) {
  const t = item.json || {};
  const author = pickAuthor(t);
  if (!author) continue;

  const text = String(t.text || t.full_text || t.fullText || '');
  const createdAtRaw = t.createdAt || t.created_at || t.date || '';
  const post_id = String(t.id || t.id_str || t.tweetId || '');
  const post_url = String(t.url || t.tweetUrl ||
    (post_id && author ? `https://twitter.com/${author}/status/${post_id}` : ''));

  const likes = Number(t.likeCount || t.favorite_count || t.likes || 0);
  const views = Number(t.viewCount || t.views || t.impressionsCount || 0);
  const comments = Number(t.replyCount || t.reply_count || t.comments || 0);
  const reposts = Number(t.retweetCount || t.retweet_count || t.reposts || 0);
  const bookmarks = Number(t.bookmarkCount || t.bookmark_count || 0);

  const imageUrl = pickImage(t);
  const hasVideo = Array.isArray(t.media) && t.media.some(m =>
    typeof m === 'object' && (m.type === 'video' || m.type === 'animated_gif')
  );
  const isReply = Boolean(t.isReply || t.in_reply_to_status_id || t.inReplyToStatusId);
  const isRepost = Boolean(t.isRetweet || t.retweeted_status || t.isRepost);

  let createdMs = null;
  if (createdAtRaw) {
    const d = new Date(createdAtRaw);
    if (!isNaN(d.getTime())) createdMs = d.getTime();
  }
  const post_age_hours = createdMs
    ? Math.max(0.01, (ctx.nowMs - createdMs) / 3600000)
    : 9999;
  const engagement_total = likes + comments * 3 + reposts * 4 + bookmarks * 2;
  const engagement_rate = views > 0 ? engagement_total / views : 0;

  out.push({
    json: {
      run_id: ctx.run_id, scraped_at: ctx.scraped_at, target_window: ctx.target_window,
      platform: 'x',
      author,
      author_followers: pickFollowers(t),
      creator_type: '',
      niche: ctx.niche_name || '',
      source_priority: 'medium',
      post_id, post_url,
      created_at: createdMs ? new Date(createdMs).toISOString() : '',
      created_at_ms: createdMs || 0,
      post_age_hours: Math.round(post_age_hours * 100) / 100,
      text,
      image_url: imageUrl, drive_image_url: '',
      likes, views, comments, reposts, bookmarks,
      engagement_total,
      engagement_rate: Math.round(engagement_rate * 10000) / 10000,
      has_image: imageUrl !== '', has_video: hasVideo,
      is_reply: isReply, is_repost: isRepost
    }
  });
}
return out;

// Build Instagram input for apify/instagram-scraper using hashtag explore URLs.
// Each hashtag becomes a directUrl pointing at the explore/tags page.
const ctx = $input.first().json;

const hashtags = String(ctx.hashtags_instagram || '')
  .split(',').map(s => s.trim().replace(/^#/, '')).filter(Boolean);

if (hashtags.length === 0) {
  return [{ json: { _empty: true, stage: 'prepare_ig_no_tags', run_id: ctx.run_id, platform: 'instagram' } }];
}

const directUrls = hashtags.map(h => `https://www.instagram.com/explore/tags/${h}/`);

const apifyBody = {
  directUrls,
  resultsType: 'posts',
  resultsLimit: 30,
  addParentData: false
};

return [{ json: { ...ctx, apifyBody, platform: 'instagram' } }];

// Normalize Instagram posts (apify/instagram-scraper hashtag results).
const ctx = $('Initialize Run').first().json;
const items = $input.all();

if (items.length === 0) {
  return [{ json: { _empty: true, stage: 'normalize_instagram', run_id: ctx.run_id } }];
}

const out = [];
for (const item of items) {
  const t = item.json || {};
  const author = String(t.ownerUsername || t.username || t.owner?.username || '').toLowerCase();
  if (!author) continue;

  const text = String(t.caption || t.text || '');
  const createdAtRaw = t.timestamp || t.takenAtTimestamp || t.taken_at || '';
  const post_id = String(t.id || t.shortCode || t.shortcode || '');
  const shortCode = t.shortCode || t.shortcode || '';
  const post_url = String(t.url || (shortCode ? `https://www.instagram.com/p/${shortCode}/` : ''));

  const likes = Number(t.likesCount || t.likes || 0);
  const views = Number(t.videoViewCount || t.videoPlayCount || t.viewCount || 0);
  const comments = Number(t.commentsCount || t.comments || 0);
  const reposts = 0;
  const bookmarks = 0;
  const author_followers = Number(t.ownerFollowersCount || t.followersCount || 0);

  const imageUrl = String(t.displayUrl || (Array.isArray(t.images) && t.images[0]) || '');
  const typeStr = String(t.type || '').toLowerCase();
  const hasVideo = Boolean(t.videoUrl) || typeStr === 'video' || typeStr === 'reel';

  let createdMs = null;
  if (createdAtRaw) {
    if (typeof createdAtRaw === 'number' && createdAtRaw < 1e12) {
      createdMs = createdAtRaw * 1000;
    } else {
      const d = new Date(createdAtRaw);
      if (!isNaN(d.getTime())) createdMs = d.getTime();
    }
  }
  const post_age_hours = createdMs
    ? Math.max(0.01, (ctx.nowMs - createdMs) / 3600000)
    : 9999;
  const engagement_total = likes + comments * 3 + reposts * 4 + bookmarks * 2;
  const engagement_rate = views > 0 ? engagement_total / views : 0;

  out.push({
    json: {
      run_id: ctx.run_id, scraped_at: ctx.scraped_at, target_window: ctx.target_window,
      platform: 'instagram',
      author,
      author_followers,
      creator_type: '',
      niche: ctx.niche_name || '',
      source_priority: 'medium',
      post_id, post_url,
      created_at: createdMs ? new Date(createdMs).toISOString() : '',
      created_at_ms: createdMs || 0,
      post_age_hours: Math.round(post_age_hours * 100) / 100,
      text,
      image_url: imageUrl, drive_image_url: '',
      likes, views, comments, reposts, bookmarks,
      engagement_total,
      engagement_rate: Math.round(engagement_rate * 10000) / 10000,
      has_image: imageUrl !== '' && !hasVideo, has_video: hasVideo,
      is_reply: false, is_repost: false
    }
  });
}
return out;

// Build TikTok input for clockworks/tiktok-scraper using hashtag mode.
const ctx = $input.first().json;

const hashtags = String(ctx.hashtags_tiktok || '')
  .split(',').map(s => s.trim().replace(/^#/, '')).filter(Boolean);

if (hashtags.length === 0) {
  return [{ json: { _empty: true, stage: 'prepare_tt_no_tags', run_id: ctx.run_id, platform: 'tiktok' } }];
}

const apifyBody = {
  hashtags,
  resultsPerPage: 30,
  shouldDownloadVideos: false,
  shouldDownloadCovers: false,
  shouldDownloadSubtitles: false
};

return [{ json: { ...ctx, apifyBody, platform: 'tiktok' } }];

// Normalize TikTok posts (clockworks/tiktok-scraper hashtag results).
const ctx = $('Initialize Run').first().json;
const items = $input.all();

if (items.length === 0) {
  return [{ json: { _empty: true, stage: 'normalize_tiktok', run_id: ctx.run_id } }];
}

const out = [];
for (const item of items) {
  const t = item.json || {};
  const author = String(t.authorMeta?.name || t.authorMeta?.nickName || t.author || '').toLowerCase();
  if (!author) continue;

  const text = String(t.text || t.desc || '');
  const createdAtRaw = t.createTimeISO || t.createTime || '';
  const post_id = String(t.id || '');
  const post_url = String(t.webVideoUrl || t.videoUrl ||
    (post_id && author ? `https://www.tiktok.com/@${author}/video/${post_id}` : ''));

  const likes = Number(t.diggCount || t.likes || 0);
  const views = Number(t.playCount || t.views || 0);
  const comments = Number(t.commentCount || t.comments || 0);
  const reposts = Number(t.shareCount || t.shares || 0);
  const bookmarks = Number(t.collectCount || 0);
  const author_followers = Number(t.authorMeta?.fans || t.authorMeta?.followers || 0);

  const coverUrl = String(t.videoMeta?.coverUrl || t.cover || '');

  let createdMs = null;
  if (createdAtRaw) {
    if (typeof createdAtRaw === 'number' && createdAtRaw < 1e12) {
      createdMs = createdAtRaw * 1000;
    } else {
      const d = new Date(createdAtRaw);
      if (!isNaN(d.getTime())) createdMs = d.getTime();
    }
  }
  const post_age_hours = createdMs
    ? Math.max(0.01, (ctx.nowMs - createdMs) / 3600000)
    : 9999;
  const engagement_total = likes + comments * 3 + reposts * 4 + bookmarks * 2;
  const engagement_rate = views > 0 ? engagement_total / views : 0;

  out.push({
    json: {
      run_id: ctx.run_id, scraped_at: ctx.scraped_at, target_window: ctx.target_window,
      platform: 'tiktok',
      author,
      author_followers,
      creator_type: '',
      niche: ctx.niche_name || '',
      source_priority: 'medium',
      post_id, post_url,
      created_at: createdMs ? new Date(createdMs).toISOString() : '',
      created_at_ms: createdMs || 0,
      post_age_hours: Math.round(post_age_hours * 100) / 100,
      text,
      image_url: coverUrl, drive_image_url: '',
      likes, views, comments, reposts, bookmarks,
      engagement_total,
      engagement_rate: Math.round(engagement_rate * 10000) / 10000,
      has_image: false, has_video: true,
      is_reply: false, is_repost: false
    }
  });
}
return out;

// Build YouTube Shorts input for streamers/youtube-scraper.
// Mix keyword search URLs (filtered to recent uploads) and hashtag URLs.
const ctx = $input.first().json;

const keywords = String(ctx.keywords || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const hashtags = String(ctx.hashtags_youtube || '')
  .split(',').map(s => s.trim().replace(/^#/, '')).filter(Boolean);

const startUrls = [
  // Search URL with sp=CAI%253D = "Sort by Upload Date"
  ...keywords.map(k => ({
    url: `https://www.youtube.com/results?search_query=${encodeURIComponent(k + ' #shorts')}&sp=CAI%253D`
  })),
  ...hashtags.map(h => ({
    url: `https://www.youtube.com/hashtag/${h}/shorts`
  }))
];

if (startUrls.length === 0) {
  return [{ json: { _empty: true, stage: 'prepare_yt_no_inputs', run_id: ctx.run_id, platform: 'youtube' } }];
}

const apifyBody = {
  startUrls,
  maxResults: 5,
  maxResultsShorts: 5,
  downloadSubtitles: false
};

return [{ json: { ...ctx, apifyBody, platform: 'youtube' } }];

// Normalize YouTube Shorts posts (streamers/youtube-scraper search/hashtag output).
const ctx = $('Initialize Run').first().json;
const items = $input.all();

if (items.length === 0) {
  return [{ json: { _empty: true, stage: 'normalize_youtube', run_id: ctx.run_id } }];
}

function normAuthor(raw) {
  return String(raw || '').replace('@', '').toLowerCase().trim();
}

const out = [];
for (const item of items) {
  const t = item.json || {};
  const author = normAuthor(
    t.channelName || t.channel?.name || t.channelUsername || t.author || ''
  );
  if (!author) continue;

  const text = String(t.title || t.text || '');
  const createdAtRaw = t.date || t.uploadDate || t.publishedAt || '';
  const post_id = String(t.id || t.videoId || '');
  const post_url = String(t.url || (post_id ? `https://www.youtube.com/shorts/${post_id}` : ''));

  const likes = Number(t.likes || t.likeCount || 0);
  const views = Number(t.viewCount || t.views || 0);
  const comments = Number(t.commentsCount || t.commentCount || 0);
  const reposts = 0;
  const bookmarks = 0;
  const author_followers = Number(t.channelSubscriberCount || t.subscribers || 0);

  const imageUrl = String(t.thumbnailUrl || t.thumbnail || '');

  let createdMs = null;
  if (createdAtRaw) {
    const d = new Date(createdAtRaw);
    if (!isNaN(d.getTime())) createdMs = d.getTime();
  }
  const post_age_hours = createdMs
    ? Math.max(0.01, (ctx.nowMs - createdMs) / 3600000)
    : 9999;
  const engagement_total = likes + comments * 3 + reposts * 4 + bookmarks * 2;
  const engagement_rate = views > 0 ? engagement_total / views : 0;

  out.push({
    json: {
      run_id: ctx.run_id, scraped_at: ctx.scraped_at, target_window: ctx.target_window,
      platform: 'youtube',
      author,
      author_followers,
      creator_type: '',
      niche: ctx.niche_name || '',
      source_priority: 'medium',
      post_id, post_url,
      created_at: createdMs ? new Date(createdMs).toISOString() : '',
      created_at_ms: createdMs || 0,
      post_age_hours: Math.round(post_age_hours * 100) / 100,
      text,
      image_url: imageUrl, drive_image_url: '',
      likes, views, comments, reposts, bookmarks,
      engagement_total,
      engagement_rate: Math.round(engagement_rate * 10000) / 10000,
      has_image: false, has_video: true,
      is_reply: false, is_repost: false
    }
  });
}
return out;

// Keep posts within configured time window AND drop replies/reposts.
// Uses windowMs from Initialize Run (computed from time_window_days).
const ctx = $('Initialize Run').first().json;
const items = $input.all();

const kept = items.filter(item => {
  const p = item.json;
  if (p._empty) return false;
  if (!p.created_at_ms) return false;
  if (p.created_at_ms < ctx.windowMs) return false;
  if (p.is_repost) return false;
  if (p.is_reply) return false;  // drop "see thread" replies
  return true;
});

if (kept.length === 0) {
  return [{ json: { _empty: true, stage: 'filter_window', run_id: ctx.run_id } }];
}
return kept;

// Cross-run dedup: skip posts already in Raw_Posts, plus within-run dedup.
//
// Lighter alternative if Raw_Posts gets huge: disconnect Load Existing Raw Posts
// and replace `existingRows` below with `[]`.
const ctx = $('Initialize Run').first().json;
const incoming = $('Filter Last N Days').all().filter(i => !i.json._empty);

const existingRows = $input.all();
const existingUrls = new Set();
const existingIds = new Set();
for (const row of existingRows) {
  const r = row.json || {};
  if (r.post_url) existingUrls.add(String(r.post_url).trim());
  if (r.post_id) existingIds.add(String(r.post_id).trim());
}

const seen = new Set();
const out = [];

function dedupeKey(p) {
  if (p.post_id) return `id:${p.post_id}`;
  if (p.post_url) return `url:${p.post_url}`;
  const head = String(p.text || '').slice(0, 100);
  return `hash:${p.author}|${p.created_at}|${head}`;
}

for (const item of incoming) {
  const p = item.json;
  const key = dedupeKey(p);
  if (seen.has(key)) continue;
  if (p.post_id && existingIds.has(p.post_id)) continue;
  if (p.post_url && existingUrls.has(p.post_url)) continue;
  seen.add(key);
  out.push({ json: p });
}

if (out.length === 0) {
  return [{ json: { _empty: true, stage: 'dedupe', run_id: ctx.run_id } }];
}
return out;

// Calculate raw_virality_score (0-100) and detect content pattern.
// min_views threshold pulled from config (Initialize Run).
const ctx = $('Initialize Run').first().json;
const minViews = Number(ctx.min_views) || 5000;

const items = $input.all().filter(i => !i.json._empty);
if (items.length === 0) return [{ json: { _empty: true, stage: 'score' } }];

const PATTERNS = {
  breaking_ai_news: [
    /\b(breaking|just announced|just released|just dropped|today.{0,15}released)\b/i,
    /\b(openai|anthropic|google|deepmind|meta|xai)\b.{0,40}\b(announce|release|launch|unveil)/i
  ],
  new_ai_tool: [/\b(new tool|introducing|launched|just shipped|now available|out now)\b/i],
  tutorial: [/\b(how to|step.by.step|tutorial|guide|walkthrough|here.s how)\b/i],
  contrarian_opinion: [/\b(unpopular|hot take|nobody is talking|controversial|i disagree)\b/i],
  benchmark: [/\b(benchmark|beats|outperforms|sota|state.of.the.art|score|leaderboard|eval)\b/i],
  workflow: [/\b(workflow|automation|pipeline|i built|i automated|n8n|zapier|make)\b/i],
  prompt_framework: [/\b(prompt|framework|system prompt|template|meta.prompt)\b/i],
  ai_agent: [/\b(ai agent|autonomous agent|agentic|multi.agent|tool.use)\b/i],
  business_automation: [/\b(business|saas|startup|revenue|customers|automate.*work)\b/i],
  generative_media: [/\b(image gen|video gen|midjourney|sora|runway|flux|nano banana|veo|kling|pika|heygen)\b/i],
  drama: [/\b(drama|fired|lawsuit|controversy|leaked|scandal|beef)\b/i],
  list_thread: [/^\d+[\.\)]\s/m, /\bthread\b/i, /^\u{1F9F5}/mu, /\bmega.thread\b/i],
  resource_toolkit: [/\b(toolkit|resources|list of|free tools|cheat sheet|stack)\b/i]
};

const PATTERN_VALUE = {
  breaking_ai_news: 15, new_ai_tool: 14, ai_agent: 14, workflow: 13,
  business_automation: 13, tutorial: 12, generative_media: 12,
  benchmark: 11, contrarian_opinion: 11, resource_toolkit: 11,
  prompt_framework: 10, list_thread: 9, drama: 6, general: 5
};

function detectPattern(text) {
  const t = String(text || '');
  for (const [k, regs] of Object.entries(PATTERNS)) {
    if (regs.some(r => r.test(t))) return k;
  }
  return 'general';
}

const out = [];
for (const item of items) {
  const p = { ...item.json };

  // Engagement floor (uses configured min_views)
  const minByCount = p.likes + p.comments + p.reposts;
  const meets_min_engagement =
    p.views >= minViews || p.likes >= 50 || p.comments >= 5 ||
    p.reposts >= 5 || minByCount >= 20;

  const engagement_velocity = p.engagement_total / Math.max(p.post_age_hours, 0.5);
  const content_pattern = detectPattern(p.text);

  // Velocity 0–30 — calibrated so 200/h ≈ 30 points.
  let velocityScore = Math.min(30, (engagement_velocity / 200) * 30);
  if (!isFinite(velocityScore) || velocityScore < 0) velocityScore = 0;

  // Engagement rate 0–20.
  let rateScore;
  if (p.views > 0) {
    rateScore = Math.min(20, p.engagement_rate * 1000);
  } else {
    rateScore = Math.min(10, p.engagement_total / 50);
  }

  // Recency 0–15 — fresher = higher (now over 5-day window).
  // 120 hours = 0 points, 0 hours = 15 points.
  const recencyScore = Math.max(0, 15 * (1 - p.post_age_hours / 120));

  // Pattern 0–15
  const patternScore = PATTERN_VALUE[content_pattern] || 5;

  // Media bonus 0–5
  const mediaBonus = p.has_video ? 5 : (p.has_image ? 3 : 0);

  // Discussion 0–5
  const replyRatio = p.likes > 0 ? p.comments / p.likes : 0;
  const discussionBonus = Math.min(5, replyRatio * 50);

  // Underdog bonus 0–10 — small accounts hitting big numbers.
  // If we have follower count and views, reward high view-per-follower ratio.
  let underdogBonus = 0;
  if (p.author_followers > 0 && p.views > 0) {
    const ratio = p.views / p.author_followers;
    if (ratio > 5) underdogBonus = 10;
    else if (ratio > 2) underdogBonus = 6;
    else if (ratio > 1) underdogBonus = 3;
  }

  let raw =
    velocityScore + rateScore + recencyScore +
    patternScore + mediaBonus + discussionBonus + underdogBonus;

  raw = Math.max(0, Math.min(100, Math.round(raw)));

  out.push({
    json: {
      ...p,
      content_pattern,
      engagement_velocity: Math.round(engagement_velocity * 100) / 100,
      raw_virality_score: raw,
      meets_min_engagement,
      status: meets_min_engagement ? 'scored' : 'low_engagement'
    }
  });
}

return out;

