const ctx = $('Initialize Run').first().json;
const input = $input.first().json || {};

function tryParseString(s) {
  if (typeof s !== 'string') return null;
  const cleaned = s.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const arrM = cleaned.match(/\[[\s\S]*\]/);
  const objM = cleaned.match(/\{[\s\S]*\}/);
  const cand = arrM ? arrM[0] : (objM ? objM[0] : null);
  if (cand) { try { return JSON.parse(cand); } catch (e) {} }
  return null;
}

function findIdeas(node, depth = 0) {
  if (node == null || depth > 6) return null;
  if (typeof node === 'string') return findIdeas(tryParseString(node), depth + 1);
  if (Array.isArray(node)) {
    if (node.length && typeof node[0] === 'object' && (node[0].idea_title || node[0].hook_ro || node[0].hook)) return node;
    return null;
  }
  if (typeof node !== 'object') return null;
  if (Array.isArray(node.ideas)) return node.ideas;
  if (Array.isArray(node.results)) return node.results;
  if (node.idea_title) return [node];
  for (const key of ['message', 'content', 'output', 'text', 'data']) {
    if (node[key] != null) {
      const found = findIdeas(node[key], depth + 1);
      if (found) return found;
    }
  }
  if (Array.isArray(node.choices) && node.choices[0]) {
    const found = findIdeas(node.choices[0], depth + 1);
    if (found) return found;
  }
  return null;
}

// Pull source posts so we can compute avg_views per idea (matched by source_url).
const sourcePosts = $('Select Top Viral Signals').all()
  .filter(i => !i.json._empty)
  .map(i => i.json);

// Average views across all top posts (used as fallback if URL match fails).
const allViews = sourcePosts.map(p => Number(p.views) || 0).filter(v => v > 0);
const overallAvg = allViews.length
  ? Math.round(allViews.reduce((a, b) => a + b, 0) / allViews.length)
  : 0;

const ideas = findIdeas(input) || [];

if (ideas.length === 0) {
  return [{ json: { _parse_error: true, run_id: ctx.run_id, raw_output: JSON.stringify(input).slice(0, 1500) } }];
}

return ideas.map(o => {
  o = o || {};
  const url = String(o.source_url || '');
  const match = sourcePosts.find(p => p.post_url === url);
  const avg_views = match ? (Number(match.views) || 0) : overallAvg;

  return {
    json: {
      idea_title: String(o.idea_title || ''),
      business_value: String(o.business_value || ''),
      why_it_works: String(o.why_it_works || ''),
      hook_ro: String(o.hook_ro || o.hook || ''),
      script_angle_ro: String(o.script_angle_ro || o.script_angle || ''),
      avg_views
    }
  };
});

// Keep ideas with final_score >= 70, top 10. Otherwise top 3 marked needs_review.
const items = $input.all().filter(i => !i.json._parse_error);
if (items.length === 0) {
  return [{ json: { _empty: true, stage: 'rank_ideas' } }];
}

items.sort((a, b) => b.json.final_score - a.json.final_score);

const high = items.filter(i => i.json.final_score >= 70).slice(0, 10);
if (high.length > 0) return high;

return items.slice(0, 3).map(i => ({
  json: { ...i.json, status: 'needs_review' }
}));

const ctx = $('Initialize Run').first().json;

let rawCount = 0;
try {
  rawCount = ($('Calculate Virality Scores').all() || []).filter(i => !i.json._empty).length;
} catch (e) {}

let filteredCount = 0;
try {
  filteredCount = ($('Select Top Viral Signals').all() || []).filter(i => !i.json._empty).length;
} catch (e) {}

const ideas = $input.all().filter(i => !i.json._empty && !i.json._parse_error);
const finalCount = ideas.length;

let topTitle = '—';
let topScore = 0;
if (finalCount > 0) {
  const sorted = [...ideas].sort((a, b) => b.json.final_score - a.json.final_score);
  topTitle = sorted[0].json.idea_title || '—';
  topScore = sorted[0].json.final_score || 0;
}

const text =
`AI Content Radar finished.
Niche: ${ctx.niche_name}
Run: ${ctx.run_id}
Window: last ${ctx.time_window_days} days
Raw posts: ${rawCount}
Filtered posts: ${filteredCount}
Final ideas: ${finalCount}
Top idea: ${topTitle} — score ${topScore}`;

return [{ json: { run_id: ctx.run_id, summary_text: text, finalCount } }];

